#!/usr/bin/env bash
# dx-install/prepare.sh · generated by the DX Installer Wizard on 2026-11-10 08:39 UTC for dx-demo.apps.promox.europesip-lab.com · installer v2.7.0-dev · Kubernetes · ingress-nginx (Ingress) · Helm 4 (BUILD-INFO.txt)
# Webinar phase 1: the namespace of the third-party tools, OpenLDAP and PostgreSQL, then stops (the environment is ready for the session).
#
# Usage:  ./prepare.sh              run the steps (without the optional checks); asks for confirmation
#         ./prepare.sh --verify     also run the optional checks
#         ./prepare.sh --from ID    resume from a step (see --list)
#         ./prepare.sh --to ID      stop after a step
#         ./prepare.sh --list       list the steps
#         ./prepare.sh --yes        do not ask for confirmation
#         ./prepare.sh --pause      show each command and wait for Enter before running it (presenter mode)
#         ./prepare.sh --collect [CASE]   collect the data HCL Support asks for (read-only, .tar.gz)
#         ./prepare.sh --cleanup    delete everything this installation created, to start again
set -Eeuo pipefail
cd "$(dirname "$0")"
# Downloads are retried (GitHub, Helm repositories and registries answer 503/504 at times); arguments are not printed
retry() { local i; for i in 1 2 3 4 5; do if "$@"; then return 0; fi; [ $i = 5 ] && return 1; echo "  ↻ download failed, retry $i/4 in 20 s" >&2; sleep 20; done; }
# Helm 3 or 4: the folder is generated for one of them (BUILD-INFO.txt); the flags that only exist in Helm 4
# are adapted when the other one is found (Helm 3: --wait=legacy -> --wait, no --force-conflicts)
HELM_MAJOR=$(helm version --template '{{.Version}}' 2>/dev/null | sed -E 's/^v?([0-9]+).*/\1/')
helm_args() { local a; HARGS=(); for a in "$@"; do
  if [ "$HELM_MAJOR" = 3 ]; then case "$a" in --wait=*) a=--wait ;; --force-conflicts|--server-side|--server-side=*) continue ;; esac; fi
  HARGS+=("$a"); done; }
rhelm() {   # helm upgrade: retried only when the chart could not be downloaded
  local i f; f=$(mktemp); helm_args "$@"
  for i in 1 2 3 4 5; do
    if helm "${HARGS[@]}" 2>&1 | tee "$f"; then rm -f "$f"; return 0; fi
    if [ $i = 5 ] || ! grep -qiE 'failed to fetch|failed to download|50[234]|gateway time-?out|tls handshake timeout|connection reset|i/o timeout|no such host|unexpected eof' "$f"; then rm -f "$f"; return 1; fi
    echo "  ↻ the chart could not be downloaded, retry $i/4 in 30 s" >&2; sleep 30
  done
}

VERIFY=0; PAUSE=0; FROM=''; TO=''; YES=0; LIST=0; COLLECT=0; CASE=''; CLEANUP=0
while [ $# -gt 0 ]; do
  case "$1" in
    --verify) VERIFY=1 ;; --no-verify) VERIFY=0 ;; --pause) PAUSE=1 ;; --no-pause) PAUSE=0 ;; --from) FROM="${2:-}"; shift ;; --to) TO="${2:-}"; shift ;; --yes|-y) YES=1 ;; --list) LIST=1 ;; --cleanup) CLEANUP=1 ;;
    --collect) COLLECT=1; case "${2:-}" in ''|-*) ;; *) CASE="$2"; shift ;; esac ;;
    -h|--help) sed -n '4,15p' "$0"; exit 0 ;;
    *) echo "Unknown option: $1 (see --help)"; exit 1 ;;
  esac; shift
done

IDS=('P-1' 'P-2' 'P-3' 'P-4' 'P-5' 'P-6')
LABS=('Webinar preparation' 'Webinar preparation' 'Webinar preparation' 'Webinar preparation' 'Webinar preparation' 'Webinar preparation')
TITLES=('Check the cluster' 'Namespace for the third-party tools' 'Corporate CAs (directory and databases): internals-ca/ and the server certificates' 'OpenLDAP with the demo users' 'Check groups and members (optional)' 'PostgreSQL 18: CloudNativePG operator, users and cluster')
OPT=(0 0 0 0 1 0)

# P-1 · Check the cluster
step_0() {
kubectl get nodes
kubectl get storageclass dx-deploy-rwo dx-deploy-rwx
kubectl get ingressclass nginx || echo "IngressClass nginx not found (k3s creates traefik when it starts)"
}

# P-2 · Namespace for the third-party tools
step_1() {
kubectl apply -f lab-base/namespace-shared.yaml
}

# P-3 · Corporate CAs (directory and databases): internals-ca/ and the server certificates
step_2() {
mkdir -p internals-ca prep-pki
[ -f prep-pki/corporate-directory-ca.key ] || openssl req -x509 -newkey rsa:3072 -nodes -sha256 -days 3650 \
  -keyout prep-pki/corporate-directory-ca.key -out internals-ca/corporate-directory-ca.crt -subj "/C=ES/O=EUROPESIP/OU=Corporate IT/CN=EUROPESIP Corporate Directory Root CA"
[ -f prep-pki/corporate-database-ca.key ] || openssl req -x509 -newkey rsa:3072 -nodes -sha256 -days 3650 \
  -keyout prep-pki/corporate-database-ca.key -out internals-ca/corporate-database-ca.crt -subj "/C=ES/O=EUROPESIP/OU=Corporate IT/CN=EUROPESIP Corporate Database Root CA"
[ -f prep-pki/openldap.crt ] || { openssl req -new -newkey rsa:2048 -nodes -keyout prep-pki/openldap.key -out prep-pki/openldap.csr \
  -subj "/C=ES/O=EUROPESIP/OU=Corporate IT/CN=openldap.dx-shared.svc.cluster.local" && \
  openssl x509 -req -in prep-pki/openldap.csr -CA internals-ca/corporate-directory-ca.crt -CAkey prep-pki/corporate-directory-ca.key -CAcreateserial -sha256 -days 825 \
  -extfile prep-pki/openldap.ext -out prep-pki/openldap.crt; }
[ -f prep-pki/postgres.crt ] || { openssl req -new -newkey rsa:2048 -nodes -keyout prep-pki/postgres.key -out prep-pki/postgres.csr \
  -subj "/C=ES/O=EUROPESIP/OU=Corporate IT/CN=dx-pg-rw.dx-shared.svc.cluster.local" && \
  openssl x509 -req -in prep-pki/postgres.csr -CA internals-ca/corporate-database-ca.crt -CAkey prep-pki/corporate-database-ca.key -CAcreateserial -sha256 -days 825 \
  -extfile prep-pki/postgres.ext -out prep-pki/postgres.crt; }
kubectl -n dx-shared create secret generic openldap-tls --type=kubernetes.io/tls --from-file=tls.crt=prep-pki/openldap.crt \
  --from-file=tls.key=prep-pki/openldap.key --from-file=ca.crt=internals-ca/corporate-directory-ca.crt --dry-run=client -o yaml | kubectl apply -f -
kubectl -n dx-shared create secret generic dx-corporate-directory-ca --from-file=ca.crt=internals-ca/corporate-directory-ca.crt --dry-run=client -o yaml | kubectl apply -f -
kubectl -n dx-shared create secret tls dx-pg-tls --cert=prep-pki/postgres.crt --key=prep-pki/postgres.key --dry-run=client -o yaml | kubectl apply -f -
kubectl -n dx-shared create secret generic dx-pg-corporate-ca --from-file=ca.crt=internals-ca/corporate-database-ca.crt --dry-run=client -o yaml | kubectl apply -f -
}

# P-4 · OpenLDAP with the demo users
step_3() {
kubectl apply -f lab-ldap/secrets.openldap.yaml
kubectl -n dx-shared create configmap openldap-demo-ldif --from-file=00-demo-users.ldif=lab-ldap/demo-users.ldif --dry-run=client -o yaml | kubectl apply -f -
retry helm repo add helm-openldap https://jp-gouin.github.io/helm-openldap/
rhelm upgrade --install openldap helm-openldap/openldap-stack-ha --version 4.3.3 -n dx-shared \
  -f lab-ldap/openldap-values.yaml --wait=legacy --timeout 10m
}

# P-5 · Check groups and members (optional)
step_4() {
kubectl -n dx-shared exec openldap-0 -c openldap-stack-ha -- \
  env LDAPTLS_CACERT=/opt/bitnami/openldap/certs/ca.crt ldapsearch -x -LLL -H ldaps://localhost:1636 -D cn=admin,dc=dxdemo,dc=com -w '<REDACTED>' -b ou=groups,dc=dxdemo,dc=com cn uniqueMember
}

# P-6 · PostgreSQL 18: CloudNativePG operator, users and cluster
step_5() {
retry helm repo add cnpg https://cloudnative-pg.github.io/charts
rhelm upgrade --install cnpg cnpg/cloudnative-pg --version 0.29.1 -n dx-shared --wait=legacy --timeout 10m
kubectl apply -f lab-bbdd/secrets.yaml
kubectl -n dx-shared create configmap dx-pg-setup-sql --from-file=lab-bbdd/setup-postgres-dx.sql --dry-run=client -o yaml | kubectl apply -f -     # your table creation script
kubectl apply -f lab-bbdd/cluster-dx-pg.yaml
kubectl -n dx-shared wait clusters.postgresql.cnpg.io/dx-pg --for=condition=Ready --timeout=10m
}

B=$'\033[1m'; C=$'\033[1;36m'; G=$'\033[1;32m'; Y=$'\033[1;33m'; R=$'\033[1;31m'; N=$'\033[0m'

# --collect: data for an HCL Support case (support/collect-support-data.sh, read-only). The names of this
# installation and its secrets go in the environment: the collector uses the secrets only to mask them.
if [ $COLLECT = 1 ]; then
  export PLATFORM='kubernetes' DX_NS='dx-demo' SHARED_NS='dx-shared' DX_RELEASE='dx-deployment' IQ_RELEASE='dx-iq' SEARCH_RELEASE='dx-search'
  export HCL_HARBOR_TOKEN='<REDACTED>' OPENROUTER_API_KEY='<REDACTED>' AWS_BEARER_TOKEN_BEDROCK='' ANTHROPIC_API_KEY='' LITELLM_MASTER_KEY='<REDACTED>' WPSADMIN_PASSWORD='<REDACTED>' AD_BIND_PASSWORD='' ORACLE_DX_PASSWORD=''
  exec support/collect-support-data.sh ${CASE:+--case "$CASE"} --out .
fi

# --cleanup: the same as common/99-cleanup.sh of the labs
if [ $CLEANUP = 1 ]; then
  echo "About to delete the Helm releases, volumes and namespaces dx-demo and dx-shared (StorageClasses are kept)."
  if [ $YES = 0 ]; then read -r -p "Type 'delete' to continue: " a; [ "$a" = delete ] || { echo Cancelled; exit 1; }; fi
  set +e
  for r in $(helm list -n dx-demo -q); do echo "helm uninstall $r"; helm uninstall $r -n dx-demo --wait --timeout 10m; done
  kubectl -n dx-demo delete pvc --all --wait=false
  kubectl -n dx-shared delete clusters.postgresql.cnpg.io --all --wait=true --timeout=5m 2>/dev/null   # before its operator
  for r in $(helm list -n dx-shared -q); do echo "helm uninstall $r"; helm uninstall $r -n dx-shared --wait --timeout 10m; done
  kubectl -n dx-shared delete pvc --all --wait=false
  kubectl delete namespace dx-demo dx-shared --ignore-not-found --wait=true --timeout=10m
  echo "Done. To install again: ./prepare.sh"
  exit 0
fi

N_STEPS=${#IDS[@]}
if [ $LIST = 1 ]; then
  for i in "${!IDS[@]}"; do printf '%-6s %-42s %s\n' "${IDS[$i]}" "${LABS[$i]}" "${TITLES[$i]}"; done
  exit 0
fi
if [ -n "$FROM" ] && ! printf '%s\n' "${IDS[@]}" | grep -qx -- "$FROM"; then echo "Unknown step: $FROM (see --list)"; exit 1; fi
if [ -n "$TO" ] && ! printf '%s\n' "${IDS[@]}" | grep -qx -- "$TO"; then echo "Unknown step: $TO (see --list)"; exit 1; fi

# Prerequisites: tools, values still to fill in, and the cluster
missing=()
for c in kubectl helm openssl curl; do command -v $c >/dev/null 2>&1 || missing+=("$c"); done
[ ${#missing[@]} = 0 ] || { echo "${R}Missing tools:${N} ${missing[*]}"; exit 1; }
P=PUT-YOUR
if grep -rlq --exclude=RUNBOOK.md "$P-" .; then echo "${R}Values still to fill in${N} (replace every $P-...-HERE):"; grep -rno --exclude=RUNBOOK.md "$P-[A-Z-]*HERE" . | sort -u; exit 1; fi
[ -f lab-bbdd/setup-postgres-dx.sql ] || { echo "${R}Copy setup-postgres-dx.sql into lab-bbdd/${N} (RUNBOOK.md)"; exit 1; }
case "$HELM_MAJOR" in
  3|4) [ "$HELM_MAJOR" = 4 ] || echo "${Y}Helm $HELM_MAJOR found; this folder was generated for Helm 4: its Helm 4 flags are adapted (--wait=legacy -> --wait, no --force-conflicts).${N}" ;;
  *) echo "${R}Helm 3 or 4 is needed (found: $(helm version --short 2>/dev/null || echo none))${N}"; exit 1 ;;
esac
kubectl version --request-timeout=10s >/dev/null 2>&1 || { echo "${R}Cannot reach the cluster with kubectl${N}"; exit 1; }
echo "${B}HCL DX Compose · webinar preparation${N}"
echo "  cluster context : $(kubectl config current-context 2>/dev/null)"
echo "  DX              : https://dx-demo.apps.promox.europesip-lab.com/wps/portal"
echo "  namespaces      : dx-demo (HCL) · dx-shared (third party)"
echo "  steps           : $N_STEPS$([ $VERIFY = 0 ] && echo ', optional checks skipped (--verify to run them)')$([ -n "$FROM" ] && echo ", from $FROM")$([ -n "$TO" ] && echo ", up to $TO")"
if [ $YES = 0 ]; then read -r -p "Continue? [y/N] " a; [[ "$a" =~ ^[yYsS] ]] || { echo Cancelled; exit 1; }; fi

CUR=''
trap 'echo; echo "${R}✖ Step $CUR failed.${N} Fix the cause and resume with:  ./prepare.sh --from $CUR"' ERR
T0=$SECONDS; started=0; [ -z "$FROM" ] && started=1
for i in "${!IDS[@]}"; do
  id=${IDS[$i]}
  if [ $started = 0 ]; then [ "$id" = "$FROM" ] && started=1 || continue; fi
  if [ "${OPT[$i]}" = 1 ] && [ $VERIFY = 0 ]; then echo "${Y}-- skip${N} [$((i+1))/$N_STEPS] $id · ${TITLES[$i]}"; [ "$id" = "$TO" ] && break; continue; fi
  if [ $PAUSE = 1 ]; then
    echo; echo "${C}━━━ [$((i+1))/$N_STEPS] ${LABS[$i]} · $id · ${TITLES[$i]}${N}"
    declare -f step_$i | sed '1,2d;$d' | sed 's/^    /    /'
    read -r -p "  ${B}Enter${N} = run · ${B}s${N} = skip · ${B}q${N} = quit: " k </dev/tty || k=''
    case "$k" in s|S) echo "${Y}-- skipped${N} $id"; [ "$id" = "$TO" ] && break; continue ;; q|Q) echo "Stopped. Resume with: ./prepare.sh --from $id"; exit 0 ;; esac
  fi
  CUR=$id; t=$SECONDS
  echo
  echo "${C}━━━ [$((i+1))/$N_STEPS] ${LABS[$i]} · $id · ${TITLES[$i]}${N}  (+$(( (SECONDS-T0)/60 )) min)"
  step_$i
  echo "${G}✔ $id${N} ($(( SECONDS-t ))s)"
  [ "$id" = "$TO" ] && break
done
trap - ERR
if [ -n "$TO" ] && [ "$id" = "$TO" ] && [ $((i+1)) -lt $N_STEPS ]; then
  echo; echo "${G}${B}✔ Stopped after $TO as asked ($(( (SECONDS-T0)/60 )) min).${N}  Continue later with:  ./prepare.sh --from ${IDS[$((i+1))]}"
  exit 0
fi
echo
echo "${G}${B}✔ Environment ready for the session in $(( (SECONDS-T0)/60 )) min.${N}"
echo "  Stop here. On the day of the demo: ./demo.sh (stages 0 to 5)."

